from django.contrib.auth import validators
from django.core.exceptions import ValidationError
from django.test import SimpleTestCase


class UsernameValidatorTrailingNewlineTests(SimpleTestCase):
    def test_unicode_validator_rejects_trailing_newline(self):
        v = validators.UnicodeUsernameValidator()
        with self.assertRaises(ValidationError):
            v('username\n')

    def test_ascii_validator_rejects_trailing_newline(self):
        v = validators.ASCIIUsernameValidator()
        with self.assertRaises(ValidationError):
            v('username\n')

    def test_valid_username_still_accepted(self):
        for v in (validators.UnicodeUsernameValidator(), validators.ASCIIUsernameValidator()):
            v('user.name@example+1-x')

