from django.db.models import Avg, Sum
from django.test import TestCase

from .models import Author


class DistinctAvgSumTests(TestCase):
    @classmethod
    def setUpTestData(cls):
        Author.objects.create(name='a1', age=10)
        Author.objects.create(name='a2', age=10)
        Author.objects.create(name='a3', age=20)

    def test_allow_distinct_flag(self):
        self.assertTrue(Avg.allow_distinct)
        self.assertTrue(Sum.allow_distinct)

    def test_sum_distinct(self):
        try:
            agg = Sum('age', distinct=True)
        except TypeError as e:
            self.fail('Sum rejected distinct: %s' % e)
        result = Author.objects.aggregate(total=agg)
        self.assertEqual(result['total'], 30)

    def test_avg_distinct(self):
        try:
            agg = Avg('age', distinct=True)
        except TypeError as e:
            self.fail('Avg rejected distinct: %s' % e)
        result = Author.objects.aggregate(avg=agg)
        self.assertEqual(result['avg'], 15)

import datetime

from django.db.models import F
from django.test import TestCase

from .models import Experiment


class DurationOnlyExpressionTests(TestCase):
    @classmethod
    def setUpTestData(cls):
        cls.start = datetime.datetime(2010, 6, 25, 12, 15, 30, 747000)
        cls.estimated = datetime.timedelta(hours=1, microseconds=5)
        Experiment.objects.create(
            name='e1',
            assigned=cls.start.date(),
            completed=cls.start.date() + datetime.timedelta(2),
            estimated_time=cls.estimated,
            start=cls.start,
            end=cls.start + datetime.timedelta(2),
        )

    def _fetch(self, expression):
        qs = Experiment.objects.annotate(duration=expression)
        try:
            return list(qs)
        except Exception as e:
            self.fail(
                'Evaluating a duration-only expression raised %s: %s'
                % (type(e).__name__, e)
            )

    def test_duration_plus_timedelta(self):
        for delta in [
            datetime.timedelta(1),
            datetime.timedelta(microseconds=123),
            datetime.timedelta(days=1, seconds=3, microseconds=7),
        ]:
            with self.subTest(delta=delta):
                results = self._fetch(F('estimated_time') + delta)
                self.assertEqual(len(results), 1)
                self.assertEqual(results[0].duration, self.estimated + delta)

    def test_duration_plus_duration_field(self):
        results = self._fetch(F('estimated_time') + F('estimated_time'))
        self.assertEqual(len(results), 1)
        self.assertEqual(results[0].duration, self.estimated * 2)

import sys
from unittest import mock, skipUnless

from django.test import SimpleTestCase
from django.utils import autoreload


class TestChildArgumentsXOptions(SimpleTestCase):
    @skipUnless(sys.implementation.name == 'cpython', 'CPython only')
    @mock.patch('__main__.__spec__', None)
    @mock.patch('sys.argv', [__file__, 'runserver'])
    @mock.patch('sys.warnoptions', [])
    @mock.patch('sys._xoptions', {'utf8': True, 'a': 'b'}, create=True)
    def test_xoptions(self):
        self.assertEqual(
            autoreload.get_child_arguments(),
            [sys.executable, '-Xutf8', '-Xa=b', __file__, 'runserver'],
        )

from django.template import Context, Engine
from django.template.exceptions import TemplateSyntaxError
from django.test import SimpleTestCase
from django.utils.html import json_script


class JsonScriptOptionalIdTests(SimpleTestCase):
    def test_util_without_element_id(self):
        try:
            result = json_script({'a': '<&>'})
        except TypeError as e:
            self.fail('json_script() should accept no element_id: %s' % e)
        self.assertEqual(
            result,
            '<script type="application/json">'
            '{"a": "\\u003C\\u0026\\u003E"}</script>',
        )

    def test_filter_without_element_id(self):
        engine = Engine(builtins=['django.template.defaultfilters'])
        try:
            template = engine.from_string('{{ value|json_script }}')
        except TemplateSyntaxError as e:
            self.fail('json_script filter should work without argument: %s' % e)
        self.assertEqual(
            template.render(Context({'value': {'a': 1}})),
            '<script type="application/json">{"a": 1}</script>',
        )

from django.core import validators
from django.db.models import CharField, Value
from django.test import SimpleTestCase


class CharFieldMaxLengthValidatorTests(SimpleTestCase):
    def test_value_output_field_has_no_max_length_validator(self):
        field = Value('test')._resolve_output_field()
        self.assertIsInstance(field, CharField)
        self.assertFalse(
            any(isinstance(v, validators.MaxLengthValidator) for v in field.validators),
            'CharField without max_length must not get a MaxLengthValidator.',
        )

    def test_clean_without_max_length(self):
        field = CharField()
        try:
            result = field.clean('1', None)
        except TypeError as e:
            self.fail('clean() raised TypeError without max_length: %s' % e)
        self.assertEqual(result, '1')

    def test_max_length_validator_with_max_length(self):
        field = CharField(max_length=5)
        self.assertTrue(
            any(isinstance(v, validators.MaxLengthValidator) for v in field.validators)
        )

from decimal import Decimal

from django.core.exceptions import FieldError
from django.db.models import DecimalField, FloatField, IntegerField, Value
from django.test import SimpleTestCase


class CombinedModOutputFieldTests(SimpleTestCase):
    def _resolve(self, expr):
        try:
            return expr.output_field
        except FieldError as e:
            self.fail("output_field could not be resolved for MOD: %s" % e)

    def test_integer_mod_decimal(self):
        expr = Value(5, output_field=IntegerField()) % Value(
            Decimal("2.5"), output_field=DecimalField()
        )
        self.assertIsInstance(self._resolve(expr), DecimalField)

    def test_decimal_mod_integer(self):
        expr = Value(Decimal("5.5"), output_field=DecimalField()) % Value(
            2, output_field=IntegerField()
        )
        self.assertIsInstance(self._resolve(expr), DecimalField)

    def test_integer_mod_float(self):
        expr = Value(5, output_field=IntegerField()) % Value(
            2.5, output_field=FloatField()
        )
        self.assertIsInstance(self._resolve(expr), FloatField)

    def test_float_mod_integer(self):
        expr = Value(5.5, output_field=FloatField()) % Value(
            2, output_field=IntegerField()
        )
        self.assertIsInstance(self._resolve(expr), FloatField)

import datetime

from django.test import SimpleTestCase, override_settings
from django.utils import timezone
from django.utils.timesince import timesince


class TimesinceTzPivotTests(SimpleTestCase):
    def _timesince(self, *args):
        try:
            return timesince(*args)
        except TypeError as e:
            self.fail("timesince() raised TypeError with aware datetimes: %s" % e)

    @override_settings(USE_TZ=True)
    def test_long_interval_with_tz(self):
        now = timezone.now()
        d = now - datetime.timedelta(days=31)
        self.assertEqual(self._timesince(d), "1\xa0month")

    @override_settings(USE_TZ=True)
    def test_long_interval_with_tz_explicit_now(self):
        d = datetime.datetime(2022, 1, 1, tzinfo=datetime.timezone.utc)
        now = d + datetime.timedelta(days=31)
        self.assertEqual(self._timesince(d, now), "1\xa0month")

