import copy

import pytest

import xarray as xr


def _make_ds():
    return xr.Dataset(
        coords={'x': ['foo'], 'y': ('x', ['bar'])},
        data_vars={'z': ('x', ['baz'])})


@pytest.mark.parametrize('how', [
    'ds_deep', 'ds_shallow', 'ds_copy_copy', 'ds_deepcopy',
    'da_deep', 'da_shallow', 'da_copy_copy', 'da_deepcopy',
])
def test_copy_preserves_unicode_index_dtype(how):
    ds = _make_ds()
    da = ds.z
    if how == 'ds_deep':
        result = ds.copy(deep=True)
    elif how == 'ds_shallow':
        result = ds.copy(deep=False)
    elif how == 'ds_copy_copy':
        result = copy.copy(ds)
    elif how == 'ds_deepcopy':
        result = copy.deepcopy(ds)
    elif how == 'da_deep':
        result = da.copy(deep=True)
    elif how == 'da_shallow':
        result = da.copy(deep=False)
    elif how == 'da_copy_copy':
        result = copy.copy(da)
    else:
        result = copy.deepcopy(da)

    assert result['x'].dtype.kind == 'U'
    assert result['x'].values.dtype.kind == 'U'
    assert result['y'].dtype.kind == 'U'

import sys


def test_show_fixtures_with_bytes_param_no_byteswarning(testdir):
    testdir.makepyfile(
        """
        import pytest

        @pytest.mark.parametrize('data', [b'Hello World'])
        def test_data(data):
            pass
        """
    )
    result = testdir.run(
        sys.executable, "-bb", "-m", "pytest", "--setup-show", "-p", "no:cacheprovider"
    )
    result.stdout.no_fnmatch_line("*BytesWarning*")
    assert result.ret == 0
    result.assert_outcomes(passed=1)

from sympy.combinatorics.permutations import Permutation


def _build(cycles):
    try:
        return Permutation(cycles)
    except ValueError as e:
        assert False, "Permutation(%s) raised ValueError: %s" % (cycles, e)


def test_nondisjoint_cycles_identity():
    p = _build([[0, 1], [0, 1]])
    assert p.array_form == [0, 1]


def test_nondisjoint_cycles_left_to_right():
    p = _build([[1, 2], [2, 3]])
    assert p.array_form == [0, 3, 1, 2]

